/**
 * @name Zip Slip
 * @description Extracting files from a malicious zip archive without validating that the destination path is within the intended directory can allow an attacker to overwrite arbitrary files on the system.
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: Names from a ZipFile or similar archive
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember(["namelist", "infolist"]).getACall() and
      source = call
    )
    or
    // TarFile members
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("tarfile").getMember("open").getReturn().getMember(["getnames", "getmembers"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: File open or write operations
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potentially unsafe archive extraction (Zip Slip) from $@.", source.getNode(), "archive member"

/**
 * @name Zip Slip Vulnerability
 * @description extracting files from a malicious zip file without validating the path can allow the attacker to overwrite files on the system.
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip-enhanced
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source is the archive member name coming from namelist() or infolist()
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember(["namelist", "infolist"]).getACall() or
      call = API::moduleImport("tarfile").getMember("TarFile").getReturn().getMember(["getnames", "getmembers"]).getACall()
      |
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is the path argument to open() or similar, or implicit in extract()
    // However, extract() and extractall() often take the member as argument.
    // Let's look for the filename argument in extract()
    exists(DataFlow::CallCfgNode call |
        call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("extract").getACall() or
        call = API::moduleImport("tarfile").getMember("TarFile").getReturn().getMember("extract").getACall()
        |
        sink = call.getArg(0)
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential Zip Slip: member name from $@ flows to extraction.", source.getNode(), "archive member"
